        answer: '逻辑回归使用交叉熵损失函数（Cross-Entropy Loss），也称为对数损失（Log Loss）。对于二分类问题，假设 y ∈ {0, 1}，模型的预测值为 ŷ = σ(wᵀx) = 1/(1+e^{-wᵀx})。单个样本的损失为 L = -[y·log(ŷ) + (1-y)·log(1-ŷ)]，本质上是极大似然估计的负对数形式。对整个数据集求平均得到代价函数 J(w) = -(1/m)·Σ[y⁽ⁱ⁾log(ŷ⁽ⁱ⁾) + (1-y⁽ⁱ⁾)log(1-ŷ⁽ⁱ⁾)]。梯度推导利用 sigmoid 函数的性质 σ\\\'(z) = σ(z)(1-σ(z))，对 J(w) 求导得 ∂J/∂w = (1/m)·Σ(ŷ⁽ⁱ⁾ - y⁽ⁱ⁾)·x⁽ⁱ⁾，形式与线性回归梯度极其相似，这正是使用交叉熵而非 MSE 的优势——避免梯度消失问题。',
