    answer: '偏差（Bias）是模型预测值期望与真实值之间的差距，反映模型拟合能力；方差（Variance）是不同训练集上模型预测值的波动程度，反映模型稳定性。期望泛化误差可分解为：Error = Bias² + Variance + Irreducible Error（不可约噪声）。简单模型（如线性模型）：高偏差低方差（欠拟合）；复杂模型（如深度树）：低偏差高方差（过拟合）。总误差在两者交点处最小，这就是偏差-方差权衡。现代深度学习有时呈现"双降"（Double Descent）现象——参数多到一定程度后测试误差会再次下降，但这并不否定传统权衡理论。实战策略：集成方法（Bagging 降方差，Boosting 降偏差）、正则化（降低方差可能增加偏差）、交叉验证选最优复杂度。',
