    answer: '剪枝是防止决策树过拟合的核心手段。预剪枝（Pre-pruning）：在树生长过程中提前停止分裂，条件包括——最大深度（max_depth）、最小节点样本数（min_samples_split）、最小叶节点样本数（min_samples_leaf）、信息增益低于阈值、节点纯度足够高等。优点是训练快，缺点是可能"短视"过早停止（当前无增益但之后再分可能有增益）。后剪枝（Post-pruning）：先生成一棵完整树再自底向上修剪——(1) 代价复杂度剪枝（CCP，CART 使用）：定义损失 L(T)=误分类率+α·|T|，|T| 为叶节点数，α 越大树越小，对每个 α 找最优子树序列再用交叉验证选 α；(2) 减少错误剪枝（REP）：用验证集评估，若删除某子树后根节点替换为叶节点能降低验证误差则剪枝；(3) 悲观错误剪枝（PEP，C4.5 使用）：不用验证集，基于训练集误差加上连续性校正评估。后剪枝通常效果更好但计算量更大，实践中 XGBoost/LightGBM 使用预剪枝+正则化效果就很好。',
