    answer: '硬间隔 SVM 要求所有样本严格在决策边界两侧，要求数据完全线性可分，对异常点极为敏感——一个离群点可能完全改变决策面。现实中数据基本都不是完全线性可分的。软间隔 SVM 引入松弛变量 ξᵢ≥0 允许部分样本越界，约束条件变为 yᵢ(wᵀxᵢ+b) ≥ 1-ξᵢ，目标函数变为 min (1/2)‖w‖² + C·Σξᵢ。参数 C 是正则化系数（理论上应为惩罚系数），权衡间隔最大化和误分类容忍度：C 大 → 惩罚重 → 硬间隔效果 → 低偏差高方差（过拟合风险）；C 小 → 容忍误分类 → 更大间隔 → 高偏差低方差（欠拟合风险）。C 通过交叉验证选择 (0.01, 0.1, 1, 10, 100)。软间隔 SVM 的数学优势在于原问题始终有可行解，且支持向量是 ξᵢ>0 或恰好 ξᵢ=0 且 yᵢ(wᵀxᵢ+b)=1 的样本。',
