    answer: 'K 值选择是 K-Means 的核心难题，常用两种方法：(1) 肘部法则：计算不同 K 下的 SSE（误差平方和 SSE=Σ‖x-μ‖²），画出 K-SSE 曲线，找到"肘部"即下降速度骤减的转折点。但现实数据常无明显肘部，需要经验判断；(2) 轮廓系数：对每个样本计算 sᵢ=(bᵢ-aᵢ)/max(aᵢ,bᵢ)，其中 aᵢ 是样本到同簇其他样本的平均距离（簇内紧凑度），bᵢ 是到最近其他簇的平均距离（簇间分离度）。sᵢ 范围 [-1,1]，越接近 1 聚类越好。对每个 K 计算所有样本的平均轮廓系数，选最大的 K。肘部法则关注"组内差异"，轮廓系数兼顾"组内+组间"，后者更客观。其他方法还有 Gap Statistic（比较随机数据下的簇改善量）和业务先验知识。',
