    answer: 'PCA 的核心目标是找到投影方向，使数据投影后的方差最大化。推导过程：(1) 数据中心化：x←x-μ，使均值为 0；(2) 计算协方差矩阵 Σ = (1/n)·XᵀX；(3) 对 Σ 做特征值分解 Σ = VΛVᵀ，特征向量 vᵢ 即为第 i 主成分方向，对应特征值 λᵢ 为该方向的方差。等价推导：PCA 也可从最小化重建误差角度导出——PCA 是最优线性自编码器（线性激活+MSE损失）。降维时选前 d 个最大特征值对应的特征向量 W=[v₁,...,v_d]，投影 Z = XW，重建 X̂ = ZWᵀ。保留方差比例 = Σᵢ₌₁^d λᵢ / Σᵢ₌₁^p λᵢ，通常选 >90% 或 95% 确定 d。PCA 是无监督线性方法，优点是降维去噪，缺点是丢失可解释性（主成分是特征线性组合）且只能捕捉线性关系。',
