    answer: '聚类评估分两大类：(1) 内部指标（无标签）：轮廓系数衡量紧凑度和分离度的平衡；Davies-Bouldin 指数（DBI）：计算簇间相似度（簇内距离之和/簇心距离）的平均值，越小越好；Calinski-Harabasz 指数（CHI / 方差比准则）：簇间离散度与簇内离散度的比值，越大越好。三者各有偏好，DBI 对圆形簇好，CHI 对大样本好；(2) 外部指标（有标签时验证）：调整兰德指数（ARI）：衡量聚类划分与真实标签的一致性，校正了随机标签的期望，[-1,1] 越接近 1 越好；归一化互信息（NMI）：衡量两个分配的互信息归一化到 [0,1]；同质性/完整性/V-measure：同质性=每簇只含单一类别，完整性=每类别分在同一簇，V-measure 是两者的调和平均。',
