    answer: 'GMM 假设数据来自 K 个高斯分布的混合，每个样本以概率 πₖ 属于第 k 个高斯 N(μₖ, Σₖ)。与 K-Means 的核心区别：(1) K-Means 每个样本硬分配给一个簇，GMM 输出每个样本属于各簇的软概率（后验概率 γ(zₙₖ)）；(2) K-Means 假定簇是等方差球形，GMM 通过协方差矩阵 Σₖ 支持椭球形（full/tied/diagonal/spherical 四种模式），表达能力强；(3) K-Means 是 GMM 的特例（各簇协方差 σ²I 且 σ→0 时退化为 K-Means）。EM 算法求解：(E步) 计算后验概率 γ(zₙₖ) = πₖ·N(xₙ|μₖ,Σₖ) / Σⱼ πⱼ·N(xₙ|μⱼ,Σⱼ)；(M步) 用 γ 加权更新参数 πₖ = Nₖ/N，μₖ = (1/Nₖ)Σγ(zₙₖ)xₙ，Σₖ = (1/Nₖ)Σγ(zₙₖ)(xₙ-μₖ)(xₙ-μₖ)ᵀ。交替迭代至收敛。GMM 的缺点：需要选 K，对初始化敏感，计算协方差矩阵逆可能数值不稳定。',
