    answer: '核心区别：(1) PCA 是确定性的线性降维（矩阵分解），t-SNE 是随机的非线性降维（梯度优化）；(2) PCA 保留全局结构（方差最大方向），t-SNE 保留局部结构（相似邻居关系优先）；(3) PCA 可反向重建数据，t-SNE 不可逆。t-SNE 原理：(a) 高维用高斯分布计算样本间相似度 pⱼ|ᵢ ∝ exp(-‖xᵢ-xⱼ‖²/2σᵢ²)，对称化 pᵢⱼ=(pᵢ|ⱼ+pⱼ|ᵢ)/2n；(b) 低维用 t 分布（自由度=1）算相似度 qᵢⱼ∝(1+‖yᵢ-yⱼ‖²)⁻¹；(c) 最小化 KL 散度 KL(P‖Q)=Σpᵢⱼ·log(pᵢⱼ/qᵢⱼ)。t 分布尾部更重，高维拥挤的远距离点在低维被拉开形成更大间距，解决了"拥挤问题"。t-SNE 特别适合 2D/3D 可视化（可看到明显簇结构），但计算慢 O(n²)，不同 perplexity 结果差异大，不适合高维→高维降维和特征提取。',
