    answer: '层次聚类分为凝聚法（Agglomerative，自底向上）和分裂法（Divisive，自顶向下），凝聚法更常用。凝聚法流程：初始每个样本各为一簇 → 每步合并最近的两簇 → 重复至只剩一簇形成树状图（Dendrogram），最后切树得到所需簇数。簇间距离定义是关键：(1) Single Linkage（单链接）：d(A,B)=min_{a∈A,b∈B} d(a,b)，易产生链状"长簇"，对异常值敏感；(2) Complete Linkage（全链接）：d(A,B)=max_{a∈A,b∈B} d(a,b)，倾向生成紧凑等径簇，异常值使大簇不易合并；(3) Average Linkage（平均链接）：d(A,B)=mean_{a∈A,b∈B} d(a,b)，折中方案最常用；(4) Ward 法：合并后使得 SSE 增加最小的两个簇，Δ=SSE(A∪B)-SSE(A)-SSE(B)，倾向生成等方差球状簇。优点是无需预设 K，树状图可直观展示聚类层次，缺点是 O(n²·log n) 复杂度，大数据不适用。',
