    answer: '自动编码器是一种无监督神经网络，目标是学习恒等映射 h(f(x))≈x，结构为编码器 f: x→z（压缩到低维潜在空间）和解码器 h: z→x̂（重建原始输入）。训练损失为重建误差 L=‖x-x̂‖² 或交叉熵。核心思想：通过瓶颈层迫使网络学到数据的最优压缩表示，瓶颈层即降维后的特征。常见变种：(1) 降噪自编码器（DAE）——输入加噪，输出干净信号，强迫学鲁棒特征；(2) 稀疏自编码器——在隐藏层加 L1 约束或 KL 散度约束，限制神经元激活数量；(3) 变分自编码器（VAE）——在潜在空间加 KL 正则使之服从标准正态分布，具有生成能力 z~N(0,I)→x̂；(4) 收缩自编码器——在损失中加编码器 Jacobian 矩阵 Frobenius 范数，使得学到的表示对输入微小变化不敏感。AE 在异常检测（高重建误差=异常）、降维、去噪等方面有广泛应用。',
