    answer: '传统统计方法：(1) 3σ 法则（单变量高斯）：x 超出 [μ-3σ, μ+3σ] 判为异常，仅适合单变量正态分布；(2) 箱线图（IQR）：Q1-1.5·IQR 和 Q3+1.5·IQR 之外。密度/距离方法：(3) Isolation Forest——随机选特征和切分点建树，异常点路径短（容易被孤立），对高维数据高效；(4) LOF（局部异常因子）——比较样本局部密度与邻居的局部密度之比，适合密度不均匀的聚类型异常；(5) One-Class SVM——用 SVM 学习正常数据边界，边界外判异常。深度学习：(6) Autoencoder 重建——正常数据重建误差小，异常数据重建误差大；(7) GAN 异常检测——用无异常的生成器无法很好重建异常样本。选择原则：高维大数据 → Isolation Forest；需要有簇的局部异常 → LOF/DBSCAN；时序数据 → LSTM+重建误差。',
