    answer: 'LDA 是一种监督降维方法，与 PCA 的核心区别：(1) PCA 无监督→最大化投影方差；LDA 有监督→最大化类间散度/类内散度的比值（Fisher 准则），目标函数 J(W) = |WᵀS_B W| / |WᵀS_W W|，其中 S_B 是类间散度矩阵，S_W 是类内散度矩阵；(2) PCA 最多保留 min(n-1,p) 个成分，LDA 最多保留 C-1 个判别方向（C=类别数），因此 LDA 输出维度受限于类别数；(3) LDA 假设各类协方差相同（同方差性），若各类分布差异大则效果差；(4) PCA 降维=数据压缩，LDA 降维=找最佳分类方向。LDA 优缺点：优点是融入标签信息能提升分类准确率，降维后同类点聚拢异类远离；缺点是要求数据符合正态分布+同方差，且需要标签，对小样本高维（p>>n）场景类内散度矩阵不可逆。常先用 PCA 降维再用 LDA。',
