    answer: 'Bagging（Bootstrap Aggregating）：并行、独立训练多个弱学习器，通过 Bootstrap 采样制造数据差异性，最终投票/平均。因为各模型之间独立性假设（实际有重叠数据），方差 Var(平均)=ρσ²+(1-ρ)σ²/B，B 越大方差越小，而偏差不变（学习器相同复杂度），所以 Bagging 降低方差。Boosting：串行、自适应训练，每一步聚焦上一步的错分样本（AdaBoost 调整权重）或残差（GBDT 拟合负梯度）。每步用一个弱学习器（如短决策树）逐步修正前序模型的错误，相当于做广义加性模型的逐段逼近 F_M(x)=Σαₘ·fₘ(x)。因为每一步都在减少当前模型与真实值的差距，综合模型逐步降低偏差，但串行过程对数据扰动敏感，方差可能略增。',
