    answer: 'AdaBoost（自适应增强）是 Boosting 族先驱算法，原理：初始各样本权重相等，每轮训练弱分类器，根据分类错误率 εₘ 计算该分类器权重 αₘ = (1/2)·ln((1-εₘ)/εₘ)，然后更新样本权重——被错分的样本权重乘以 exp(αₘ) 放大，正确分类的乘以 exp(-αₘ) 缩小，下一轮分类器更关注之前被分错的样本。最终分类器 H(x) = sign(Σαₘ·hₘ(x)) 加权投票。与 GBDT 的关键区别：(1) AdaBoost 通过样本权重引导下一轮学习，GBDT 通过拟合残差（负梯度）引导；(2) AdaBoost 的 αₘ 由 εₘ 解析确定，GBDT 的学习率需手动调参；(3) AdaBoost 损失函数是指数损失 L(y,F)=e^{-yF}（数学上等价于用加权重采样的前向分步加法模型），GBDT 可自定义损失；(4) AdaBoost 对噪声和异常值特别敏感（错分样本权重指数增长），GBDT 通过步长shrinkage更鲁棒。实践中 AdaBoost 已较少使用，大多场景被 GBDT/XGBoost 取代。',
