    answer: 'Stacking（堆叠泛化）是一种两层集成架构：第一层用多个不同类型的基模型（如 SVM + RF + XGBoost + LR）做 K 折交叉验证，每折输出验证集的预测值作为第二层训练数据，第二层元模型根据这些预测做最终预测。核心要点：第一层的 K 折交叉目的不是评估而是生成无泄漏的训练特征。Blending 是 Stacking 的简化版：Holdout 方法——划分训练集和验证集，基模型用训练集训练、用验证集生成预测作为元模型输入。区别：(1) Stacking 用 K 折交叉，数据利用率更高但慢；Blending 简单快速但有数据浪费和过拟合风险；(2) Stacking 基模型需统一 K 折划分，实现复杂；Blending 各模型独立训练。元模型常用简单模型（逻辑回归或带约束的线性回归）避免二次过拟合。Stacking 在 Kaggle 竞赛中极常见，是 Top 方案标配技术。',
