    answer: '特征随机采样指每棵决策树在每次分裂时只随机考虑 m 个特征而非全部 p 个特征。典型 m=√p（分类）或 p/3（回归）。作用：(1) 降低树之间的相关性——如果每棵树都用全部特征，强特征每次都被选为分裂点，所有树长得相似，Bagging 的方差降低效果被抵消。特征采样打破这种一致性，使树更多样化；(2) 减少过拟合——单棵树复杂度降低，集成后泛化能力提升；(3) 加速训练——每次分裂只需评估 m 个特征而非 p 个；(4) 给弱特征机会——某些中等特征在部分树中得以被选中，可能发现其他树遗漏的模式。极端情况 m=1 即为完全随机决策树（Extremely Randomized Trees），泛化能力进一步强但偏差也增大。特征采样是随机森林区别于 Bagging + 决策树的关键创新。',
