    question: '梯度提升（Gradient Boosting）的数学原理是什么？为什么拟合负梯度？',
    answer: 'Gradient Boosting 是函数空间上的梯度下降。设我们希望构建强模型 F(x) 最小化损失 ΣL(yᵢ, F(xᵢ))。在第 m 轮，我们有了当前模型 F_{m-1}(x)，梯度的函数空间版本是 func. gradient：r_im = -[∂L(yᵢ, F(xᵢ))/∂F(xᵢ)]|_{F=F_{m-1}}，即损失函数对当前模型输出 F 的负偏导。在函数空间中，梯度本身是一个"方向函数" r_m(x)——它告诉我们模型输出应往哪个方向调整才能最快降低损失。因此我们用一个新的弱学习器 fₘ(x) 去拟合这个负梯度方向（即让 fₘ(x)≈r_m），然后沿该方向更新 Fₘ(x) = F_{m-1}(x) + ν·fₘ(x)（ν 为学习率/步长）。以平方损失 L=(y-F)² 为例，负梯度 r = y-F（残差），所以 GBDT 用树拟合残差是梯度提升的特例。该框架统一了任意可微损失函数下的 Boosting。',
