    answer: '集成学习效果好有两个关键条件：(1) 每个基学习器准确率至少略优于随机猜测；(2) 基学习器之间"犯不同的错误"即有多样性（Diversity）。多样性越高，投票/平均时错误互相抵消的余地越大，集成的泛化误差 Gang 越低。提高多样性的方法：(1) 数据层面——Bagging 的 Bootstrap 重采样（不同训练集）、Boosting 的序列性样本权重调整、交叉验证折的不同划分；(2) 特征层面——随机子空间法：每棵树用不同特征子集（随机森林本质就是特征采样+数据采样双随机）；(3) 算法层面——混合异质性模型（Stacking 的核心理念，如树+SVM+LR+NN，不同归纳偏置导致不同错误模式）；(4) 参数层面——同模型用不同超参数（不同深度、学习率的 XGBoost 混合）；(5) 随机种子初始化——神经网络不同随机权重初始化。但多样性不是越高越好，极端随机会导致 ACC 下降到不可接受水平，需在多样性-准确性间权衡。',
