    answer: 'Filter（过滤式）：基于特征自身统计特性独立于模型筛选。方法：(a) 方差阈值——低方差特征信息量少可剔除；(b) 相关性分析——Pearson 相关系数或互信息，选与目标相关性强的；(c) 卡方检验——分类问题衡量特征与类别独立性；(d) 信息增益/基尼重要性。优点是计算快、可规模化，缺点是不考虑特征组合效应和模型适配性。Wrapper（包裹式）：以模型性能为标准搜索最优特征子集——前向搜索（每次加一个最好特征）、后向搜索（每次删一个最弱特征）、递归特征消除（RFE：训练模型→删最不重要→重训练）。优点是效果好考虑特征交互，缺点是计算量大 O(2^n)，小数据集可用。Embedded（嵌入式）：特征选择融入模型训练——Lasso 的 L1 正则化自动产生稀疏解；树模型的 MDI 重要性；带稀疏约束的 XGBoost(reg_lambda)。嵌入式的效率和效果兼顾，是工业界主流。实战推荐：先用 Filter 粗筛降维，再用树模型重要性/正则化自动选。',
