    question: '类别特征编码的方法有哪些？One-Hot、Label 和 Target Encoding 各适用于什么场景？',
    answer: 'One-Hot 编码：创建 k 个二值列（k=类别数），每行只有一个 1。适用：无序低基数（k≤10）类别如性别、国家。不适用：高基数（城市/品牌有上千类）导致维数爆炸、稀疏矩阵训练慢。Label 编码：将类别映射为递增整数 0,1,...,k-1。适用：有序类别（教育程度、评级）和树模型（XGBoost/LightGBM 对数值编码天然可找分裂点）。不适用：线性模型和神经网络（会人为引入类别间的虚假顺序和等距假设）。Target Encoding：将每个类别替换为其目标变量的某种统计量——mean(target)、smoothing 修正后的 target 均值：encoded = (n·mean(target)+global_mean·m)/(n+m)。适用：高基数类别且目标与类别有关系。风险：标签泄漏（用目标信息编码目标本身是数据泄露），必须用交叉验证或者内置正则化。实践中 Kaggle 选手常对高基数特征先用 Target Encoding 降维，再送 XGBoost。',
