    answer: '分箱（Binning）将连续变量划分为离散区间，好处：(1) 处理异常值——极端值被归入边界桶，不像原始值那样扭曲模型；(2) 引入非线性——每个桶变成类别特征，线性模型可学习阶梯函数关系；(3) 提高稳定性——微小波动仅改变桶内值不影响桶标签；(4) 简化特征——原始连续分布复杂（如长尾收入分布），分箱后各桶更均衡。方法：(1) 等频分箱——每个桶样本数相等，对长尾分布好；(2) 等距分箱——每个桶区间宽度相同，适合均匀分布；(3) 基于决策树分箱——以目标为监督信号找最佳分裂点（类似 CART），效果最好但计算量大需防过拟合；(4) ChiMerge——从每值一个桶开始自底向上合并相邻卡方统计量（类分布相似）的桶。注意事项：分箱本质是信息损失（丢失了连续值的精细差异），树模型不需要人工分箱，逻辑回归/朴素贝叶斯适合。',
