    answer: '特征交叉是将两个及以上特征组合形成新特征，例如：年龄 × 性别、城市 × 品牌。核心动机是捕捉特征之间的交互效应（Interaction Effect），即一个特征的效应依赖于另一个特征的取值。线性模型 y=w₁x₁+w₂x₂+w₁₂x₁x₂ 中，x₁x₂ 的系数 w₁₂ 衡量的就是交互效应。不引入交叉特征时，线性模型只能学习线性可加关系，遗漏大量信息。深层原因：决策边界在特征空间可能是非轴对齐的（diagonal boundary），单特征不对齐的方向只有通过交叉特征才能表达。深度模型的隐式交叉——神经网络通过多层非线性变换自动学交叉，但宽度模型（LR/FM 等）需要显式构造。代价也是维数爆炸：n 特征两两交叉→C(n,2)个再配合类别特征→极高维稀疏特征矩阵，需要配合正则化（FTRL/L1）处理。推荐系统中 FM/FFM/DeepFM 系列模型就是对特征交叉的建模。',
