        answer: '归一化（Min-Max）公式：x\\\'=(x-min)/(max-min)，值域 [0,1]，无负数且不对分布做假设。优点是保留原始数据分布形状，适合需要非负输入的场景（如图像像素、神经网络用 sigmoid/tanh 激活时归一化到 [0,1] 或 [-1,1]）。缺点是极度依赖 min/max，有异常值时压缩大部分正常值到极小范围。标准化（Z-Score）公式：x\\\'=(x-μ)/σ，均值为 0 标准差为 1，不限制上下界。优点是对异常值相对鲁棒（超出 [-3,3] 仍有区分度），适用于大多数 ML 场景。选择原则：(1) 算法需要计算距离或梯度 → 标准化（PCA、KNN、SVM、神经网络、逻辑回归）；(2) 数据有明显上下界且需要保持分布 → 归一化；(3) 数据含异常值 → 可考虑 RobustScaler：x\\\'=(x-median)/IQR，用中位数和四分位距替代均值和标准差；(4) 树模型 → 两者都不需要。不确定时优先用标准化。',
