    answer: 'GBDT/XGBoost/LightGBM 均提供特征重要性：(1) Gain（平均增益）——特征在所有分裂中带来的平均损失减少量（增益）的加权和，反映特征的"贡献"；(2) Cover（平均覆盖率）——特征所分裂节点覆盖的样本总数或二阶梯度之和，反映特征的"使用范围"；(3) Weight（频次）——特征被选为分裂点的总次数，简单但偏向高基数特征；(4) SHAP values——基于 Shapley 值，在 GBDT 中可高效计算（TreeSHAP 算法）。主要局限性：(a) 自相关特征互相稀释——两个高度相关的特征 A 和 B，树随机选 A 或 B 分裂，A 和 B 的重要性会各自减半，而实际上缺任一个都不碍事；(b) Gain 高 ≠ 预测依赖——某些特征可能在节点分裂中被频繁用于分裂低深度节点，但实际对最终预测贡献不大；(c) 不能反映特征间的交互效应和方向。建议用排列重要性或 SHAP 作为补充验证。',
