    question: '准确率（Accuracy）、精确率（Precision）、召回率（Recall）和 F1 Score 分别是什么？如何计算？',
    answer: '四个指标由混淆矩阵的 TP/FP/FN/TN 定义：(1) Accuracy = (TP+TN)/(TP+FP+FN+TN)：预测正确的比例，最直观但类别不均衡时失效（99% 负样本全猜负 Accuracy=99%）；(2) Precision = TP/(TP+FP)：预测为正的样本中真正正的比例，"宁缺毋滥"——高精确率意味少误报（如在垃圾邮件检测中不要误删正常邮件）、侧重质量；(3) Recall = TP/(TP+FN)：真正正样本中被预测出的比例，"宁抓错不放"——高召回意味着少漏报（如癌症筛查不能漏诊）、侧重覆盖；(4) F1 Score = 2·(Precision·Recall)/(Precision+Recall)：P 和 R 的调和平均，均衡考虑两者。为何用调和平均不用算术平均？调和平均对小值更敏感，只有 P 和 R 都高时 F1 才高，杜绝一面极端高另一面很低。根据业务场景可调整 β 参数为 F_β = (1+β²)·(P·R)/(β²·P+R)，β>1 更重召回，β<1 更重精确率。',
