    question: 'ROC AUC 是什么？如何理解和计算？为什么它对类别不均衡不敏感？',
    answer: 'ROC（Receiver Operating Characteristic）曲线以 FPR（假阳性率）=FP/(FP+TN) 为横轴、TPR（真正率/召回率）=TP/(TP+FN) 为纵轴。通过逐步调低分类阈值（从严格→宽松），正样本越抓越多但负样本误判也增加，画出单调递增曲线。AUC（Area Under Curve）是 ROC 下面积：(0-1 之间)，随机分类=0.5，完美分类=1.0。AUC 的统计解释：随机选一个正样本和一个负样本，模型给正样本的打分高于负样本的概率。AUC = 1 则完全可分离；AUC=0.5 等同于随机。AUC 对类别不均衡不敏感的原因：FPR 和 TPR 的计算都除以各自类别的总数（FP/(FP+TN) 仅涉及负类，TP/(TP+FN) 仅涉及正类），即使正负样本比例从 1:1 变为 1:100，只要模型对两个类的排序能力不变，FPR/TPR 不会变，曲线位置不变。因此 AUC 是排序能力的纯净度量，适合不均衡问题。',
