    question: '混淆矩阵（Confusion Matrix）如何解读？从混淆矩阵能推导出哪些指标？',
    answer: '混淆矩阵是分类模型结果的二维表格，行=真实类别、列=预测类别，二分类有四个单元格：TP（真正例）——模型预测为正实际为正；FP（假正例）——预测为正实际为负（误报/第一类错误）；FN（假负例）——预测为负实际为正（漏报/第二类错误）；TN（真负例）——预测为负实际为负。从这四个值可导出几乎所有分类指标：(1) 准确率=(TP+TN)/总；(2) 精确率=TP/(TP+FP)；(3) 召回率/灵敏度=TP/(TP+FN)；(4) 特异度=TN/(TN+FP)，衡量对负类的识别能力；(5) F1=2TP/(2TP+FP+FN)；(6) MCC（马修斯相关系数）= (TP×TN-FP×FN)/√((TP+FP)(TP+FN)(TN+FP)(TN+FN))，[-1,1] 综合度量最全面，类别不均衡时比 F1 更可靠。多分类混淆矩阵扩展到 k×k 矩阵，对角线是各分类正确预测数，可通过宏平均/微平均计算多分类版本的 Precision/Recall/F1。混淆矩阵可视化（热力图）能快速定位哪些类别容易混淆。',
