    question: '多分类问题的宏平均（Macro）和微平均（Micro）有什么区别？',
    answer: '多分类问题中需将一个全局指标计算方式分两类。微平均（Micro）：先汇总所有类别的 TP/FP/FN/TN，再计算总体的 Precision/Recall/F1。公式：Micro-P = ΣTPᵢ/(ΣTPᵢ+ΣFPᵢ), Micro-R = ΣTPᵢ/(ΣTPᵢ+ΣFNᵢ)。因为每个样本贡献相同权重，受大类主导——某类样本越多，在指标中占比越大。当类别不均衡时微平均反映的是大类的性能。宏平均（Macro）：先独立计算每个类别的 Precisionᵢ/Recallᵢ/F1ᵢ，再取算术平均。即 Macro-P = (1/k)·ΣPᵢ。每个类别权重相等——小类与大类的指标影响力相同。当关注小类性能时用宏平均，当关注整体所有样本时用微平均。如果宏平均和微平均差距大（如 Macro-F1=0.3，Micro-F1=0.85），说明模型在小类上表现远差于大类。多分类 F1 也分 Macro-F1 和 Micro-F1，还有 Weighted-F1 = ΣwᵢF1ᵢ (wᵢ=各类样本占比)，是大类和微平均的折中。',
