    question: '对数损失（Log Loss / Cross-Entropy Loss）是什么？它在什么场景下使用？',
    answer: 'Log Loss 是评估分类模型概率输出的标准指标，计算公式：LogLoss = -(1/N) Σ [yᵢ·log(pᵢ) + (1-yᵢ)·log(1-pᵢ)]，其中 yᵢ∈{0,1} 是真实标签，pᵢ 是模型预测为类别 1 的概率。Log Loss 不仅看你是否分类正确，还看你给的置信度有多准：如果真实是 1，你预测 0.99 的损失远小于预测 0.51；反之预测 0.01 非常自信地犯错，惩罚极大。多分类扩展：LogLoss = -(1/N) Σᵢ Σⱼ yᵢⱼ·log(pᵢⱼ)，j 遍历所有类别。使用场景：(1) Kaggle 竞赛中最常被要求的分类评估指标；(2) 需要概率校准的场景（如风险评估需精准概率而非仅类别）；(3) 用作分类模型的训练损失函数（交叉熵=Log Loss 训练时的叫法）。Log Loss 对极端概率值（p 接近 0 或 1）极其敏感——一个几乎等于 0 但实际为正的样本可以爆掉整体指标。能驱动模型做好的概率校准（Platt Scaling / Isotonic Regression）。',
