    question: 'RMSE（均方根误差）和 MAE（平均绝对误差）有什么区别？各自什么时候更适用？',
    answer: 'RMSE = √[(1/n)·Σ(ŷᵢ-yᵢ)²]，MAE = (1/n)·Σ|ŷᵢ-yᵢ|。核心差异：(1) RMSE 对大误差惩罚更重（平方放大），MAE 对所有误差等权。极端误差（如预测1000实际0）在 RMSE 中贡献 10⁶ 而 MAE 仅 1000，所以 RMSE 对异常值极为敏感，异常值多时 MAE 更鲁棒；(2) 数学性质：RMSE 可导（L2），在梯度下降优化中更友好（MAE 在 0 处不可导）；(3) RMSE≥MAE 且 RMSE=MAE 当且仅当所有误差相等。两者差距越大说明误差方差（或异常值）越大，通过 RMSE-MAE 差值可以评估误差分布的异质性。使用建议：(a) 希望预测值尽可能接近真实值（中值/无偏）且异常值已有控制 → RMSE；(b) 数据有大量无法去除的异常值 → MAE；(c) 优化过程需要用可微损失函数 → RMSE/MSE；(d) Huber Loss 做折中——误差小于 δ 时用 L2，大于 δ 时用 L1，远近通吃。',
