    question: 'R²（决定系数）是什么？如何解读它的值？',
    answer: 'R² 衡量回归模型的拟合优度（goodness-of-fit），公式：R² = 1 - SS_res / SS_tot = 1 - Σ(yᵢ-ŷᵢ)² / Σ(yᵢ-ȳ)²。通俗讲：SS_tot（总平方和）衡量数据本身波动，SS_res（残差平方和）衡量模型未能解释的波动，二者比值说明"模型解释了多少比例的数据变异"。R² 范围 (-∞, 1]：(1) R²=1：完美拟合，所有残差=0；(2) R²=0.8：模型解释 80% 的方差；(3) R²=0：模型等同水平线 ȳ 预测，无解释力；(4) R²<0：模型比直接取均值预测还差（非线性模型或直接在不适当测试集评估时易出现）；(5) R²=负值也可能在带截距线性回归的测试集上出现（训练 R² 非负但测试可能负）。R² 并不完全等于 "好模型"——高 R² 不意味没有过拟合、低 R² 不意味模型无用（金融预测 R²=0.1 也是有价值的 alpha）。调整 R²（R²_adj）进一步以自由度修正，惩罚过多无关特征，更适用于模型选择。',
