    answer: 'ROC 曲线画 TPR vs FPR（真正率对假正率），PR 曲线画 Precision vs Recall。关键区别：(1) ROC 对类别不均衡不敏感——FPR=FP/(FP+TN)，真正/假正率的分母都是各自类别的总数，即使正类从 10% 降到 1%，ROC 曲线位置不变但 PR 曲线骤降；(2) PR 曲线对不均衡敏感——Precision=TP/(TP+FP)，当负类远多过正类时，哪怕一点 FP 都能大幅拉低 Precision。结论：类别均衡时两者都能用 —— ROC 更全局，PR 给出更详细的阈值层面信息；类别极其不均衡时（正类 < 1%）→ 必须用 PR 曲线或 PR-AUC —— AUC-ROC 会给出虚高的乐观评估。PR-AUC 的范围从基线（正类占比）到 1，没有数学上偏好的属性但有区分度。工程上可以用 Average Precision (AP) = PR 曲线下的近似面积，在 sklearn 的 average_precision_score 即可计算。',
