    category: 'machine-learning',
    question: '请从数学上推导梯度下降的更新公式，并解释为什么是负梯度方向。',
    answer: '梯度下降目标是最小化损失函数 J(w)。泰勒一阶展开：J(w+Δw) ≈ J(w) + ∇J(w)ᵀ·Δw。我们希望每次更新让函数值降低最大，即最小化 J(w+Δw)。令 Δw = -η·∇J(w)（负梯度方向），一阶近似下 J(w-η·∇J) ≈ J(w) - η·‖∇J(w)‖² ≤ J(w)，即每一步严格下降（忽略高阶误差）。从方向导数的角度看，单位向量 d 的方向导数为 ∇J·d = ‖∇J‖·‖d‖·cosθ，当 cosθ=-1（即 d 与梯度反向成 180°）时方向导数最小（负值最大），所以负梯度是局部最陡下降方向。最终更新公式 w:=w - η·∇J(w)，其中 η 为学习率。梯度下降的局限性：(1) 一阶方法收敛慢（二阶方法如牛顿法用 Hessian 修正方向收敛更快但计算 O(n³) 不可行）；(2) 非凸函数可能陷入鞍点（Hessian 有正有负特征值）而非局部最小值，负梯度对鞍点也近似零。',
