    question: 'Batch GD、SGD（随机梯度下降）和 Mini-Batch SGD 有什么区别？Adam 有什么优点？',
    answer: 'Batch GD（批量梯度下降）：每次用全部训练数据计算梯度，梯度方向准确但每步计算 O(N·D)，内存爆炸、缓慢且不能在线学习；(2) SGD（随机梯度下降）：每次随机一个样本计算梯度，更新快 O(D)、可用于在线学习/流式数据，但梯度有极大噪声，更新路径震荡曲折收敛慢，也不利于并行计算；(3) Mini-Batch SGD：折中方案——每次随机 B 个样本（如 32/64/128/256），梯度有一定精度的同时仍可高效计算。GPU 友好的向量化运算提升吞吐量，是实践中标准做法。Adam 是自适应学习率算法，综合了动量（Momentum：维护历史梯度指数加权平均来平滑震荡加速收敛）和 RMSprop（自适应每个参数的学习率：按参数历史梯度平方根缩放步长），核心公式：mₜ=β₁·mₜ₋₁+(1-β₁)·gₜ，vₜ=β₂·vₜ₋₁+(1-β₂)·gₜ²，偏置校正后 m̂ₜ=mₜ/(1-β₁ᵗ), v̂ₜ=vₜ/(1-β₂ᵗ)，更新 wₜ=wₜ₋₁-α·m̂ₜ/(√v̂ₜ+ε)。Adam 优点：超参数鲁棒（默认 β₁=0.9, β₂=0.999, α=0.001 即可）、适用稀疏梯度、很少需要手动调学习率。AdamW 解耦 weight decay 进一步提升泛化。',
