    question: '学习率调度（Learning Rate Scheduling）有哪些策略？为什么需要学习率衰减？',
    answer: '训练早期大步走快速逼近最优区域，后期小步走精细收敛到最小点——这是学习率衰减的核心直觉。常见策略：(1) 阶梯衰减（Step Decay）：每 N 个 epoch 学习率乘以因数 γ（如每 30 epoch γ=0.1），简单有效但需预设 epoch 数；(2) 指数衰减（Exponential Decay）：α=α₀·γ^epoch，平滑下降但后期衰减过快；(3) 余弦退火（Cosine Annealing）：αₜ=(α₀/2)·(1+cos(tπ/T))，从 α₀ 平滑降至 0，常配合 Warm Restart——周期结束后重置 α₀，多次余弦循环探索参数空间多个局部最优；(4) 线性衰减 + 预热（Warmup）：前几个 epoch 从小升到大（避免初期不稳定的高梯度和动态网络权重），再线性/余弦下降，Transformer 训练的标准做法；(5) Plateau 自适应衰减（ReduceLROnPlateau）：验证损失不再下降时自动降低学习率；(6) 循环学习率（Cyclical LR）：在一个范围内循环震幅学习率，帮助跳出局部最优和鞍点。不衰减则后期梯度下降会在最优值附近震荡不收敛。',
