    category: 'machine-learning',
    question: 'MSE（均方误差）和交叉熵损失（Cross-Entropy）分别适用于什么场景？为什么逻辑回归不能用 MSE？',
    answer: 'MSE（均方误差）适用于回归任务，公式 L=(y-ŷ)²/2，输出连续值，损失函数对称且可微。交叉熵适用于分类任务，公式 L = -[y·log(ŷ)+(1-y)·log(1-ŷ)]，衡量两个概率分布的距离（似然最大化）。为何逻辑回归不能用 MSE？两个问题：(1) 梯度消失——对 sigmoid 输出 ŷ=σ(z) 的 MSE 损失求导得 ∂L/∂z = (ŷ-y)·ŷ·(1-ŷ)，当预测值接近 0 或 1 极度自信时，ŷ(1-ŷ)≈0，梯度接近 0 参数不更新，即使预测完全错误也学不动。而交叉熵损失梯度 ∂L/∂z = ŷ-y，梯度与错误量成正比，无消失问题；(2) 损失函数非凸——MSE + sigmoid 的组合损失曲面有多个局部最优（非凸），梯度下降可能卡在差的局部解，而交叉熵 + sigmoid 的组合是凸的（二分类时），收敛到全局最优。因此机器学习中分类用交叉熵、回归用 MSE 是经过理论验证的最优组合。',
