    id: 'ml-61',
    category: 'machine-learning',
    question: '激活函数有哪些？ReLU、Sigmoid、Tanh、GELU、Swish的优缺点对比？',
    answer: '激活函数为神经网络引入非线性变换，是深度学习的核心组件。Sigmoid：σ(x)=1/(1+e^{-x})，输出 (0,1)，优点是平滑可导、输出有界（适合门控机制），缺点包括梯度饱和——当 |x|>5 时梯度接近 0，导致深层网络梯度消失；输出非零中心（均值≈0.5），后续层输入的偏移会减慢收敛；指数运算计算量大。Tanh：tanh(x)=(e^x-e^{-x})/(e^x+e^{-x})，输出 (-1,1)，零中心解决了 Sigmoid 的非零中心问题，但仍存在梯度饱和。ReLU：f(x)=max(0,x)，优点是计算极简（仅比较操作）、非饱和性——x>0 时梯度恒为 1 解决梯度消失、生物学合理性（单侧抑制）；缺点包括 Dead ReLU 问题——神经元在负区间梯度为 0 且可能永远不再激活（尤其在较大学习率或负偏置时），输出无界可能导致后续层激活值爆炸。Leaky ReLU/PReLU：f(x)=max(αx,x)，α 为小斜率（如 0.01），解决 Dead ReLU 但增加计算量。GELU：f(x)=x·Φ(x)，Φ 是标准正态 CDF，近似为 x·σ(1.702x)，在 Transformer（BERT/GPT）中广泛使用，平滑且处处可导，比 ReLU 更符合经验上的激活分布。Swish/SiLU：f(x)=x·σ(βx)，当 β=1 时即 SiLU，具备自门控（self-gating）特性——输入越大门越开，平滑非单调（可能轻微下凸），在深层网络中常优于 ReLU。选择建议：CNN 默认用 ReLU/Leaky ReLU；Transformer 用 GELU；追求极致精度可试 Swish；永远避免在隐藏层用 Sigmoid/Tanh（仅用于输出层或门控）。',
