    id: 'ml-62',
    category: 'machine-learning',
    question: '什么是梯度消失和梯度爆炸？如何解决？',
    answer: '梯度消失（Vanishing Gradient）指深层网络中反向传播时梯度逐层指数衰减，导致靠近输入的层参数几乎不更新，网络无法学到有效特征。数学原因：以 sigmoid 为例，∂σ/∂x = σ(1-σ) ≤ 0.25，经过 L 层连乘后梯度 ∝ (0.25)^L，L≥10 时梯度数量级 10^{-6}。梯度爆炸（Exploding Gradient）相反——梯度逐层指数放大，参数更新的步幅巨大导致损失震荡甚至数值溢出为 NaN，常见于 RNN 中权重矩阵的谱范数大于 1 时。解决方案分五类：(1) 激活函数——用 ReLU 替代 Sigmoid/Tanh（正区间梯度恒为 1 不衰减）；(2) 归一化层——Batch Normalization 将每层输出标准化到均值 0 方差 1，有效控制梯度尺度，Layer Normalization 常用于 Transformer/RNN；(3) 残差连接（Residual Connection）——通过跳跃连接允许梯度直接回传 y=F(x)+x，∂y/∂x=∂F/∂x+1，即使 ∂F/∂x≈0 梯度也不会消失；(4) 梯度裁剪（Gradient Clipping）——设定阈值将梯度范数截断到最大值，直接解决梯度爆炸，RNN 训练的标准操作；(5) 权重初始化——Xavier 初始化（tanh/sigmoid）和 Kaiming/He 初始化（ReLU）通过控制初始化方差 Var(w)=2/n_in 或 2/(n_in+n_out)，使每层输出的方差保持一致，防止前向传播中的信号衰减。此外 LSTM/GRU 的门控机制（遗忘门控制信息流）本质上也缓解了 RNN 的梯度消失。',
    tags: ['梯度消失', '梯度爆炸', 'Batch Normalization', '残差连接', '初始化'],
