    id: 'ml-63',
    category: 'machine-learning',
    question: 'Batch Normalization的原理是什么？为什么有效？训练和推理阶段有何不同？',
    answer: 'Batch Normalization（BN）通过对每个 mini-batch 的每一维特征做标准化，使得该层输入的分布保持稳定。训练时步骤：(1) 计算 mini-batch 均值和方差：μ_B = (1/m)Σx_i，σ²_B = (1/m)Σ(x_i - μ_B)²；(2) 标准化：x̂_i = (x_i - μ_B) / √(σ²_B + ε)；(3) 缩放和平移：y_i = γ·x̂_i + β，γ 和 β 是可学习参数恢复网络的表达能力（标准化会限制表示空间，γ 和 β 允许网络学习最优分布）。BN 有效的五个原因：(a) 减少内部协变量偏移（Internal Covariate Shift）——每层输入分布稳定，避免下层持续适应变化的输入，加速训练；(b) 平滑损失曲面——BN 使得损失函数的 Hessian 矩阵条件数降低、梯度更可预测，可使用更大学习率；(c) 正则化效果——mini-batch 的统计量带有噪声，类似 Dropout 引入随机性，减少对正则化的依赖；(d) 缓解梯度消失/爆炸——通过控制各层输出的尺度阻止信号在传播中指数衰减或放大；(e) 减弱对权重初始化的敏感性。推理阶段的区别：不再使用 mini-batch 计算均值和方差（单样本无法算 batch 统计量），而是使用训练期累积的全局移动平均 μ_running 和 σ²_running 替代。具体：训练时维护一个指数移动平均 μ_ema = α·μ_ema + (1-α)·μ_B，推理时直接使用 μ_ema 和 σ²_ema 做标准化，保证确定性输出。PyTorch 中 model.eval() 即切换到此模式。',
