    id: 'ml-64',
    category: 'machine-learning',
    question: 'Dropout的原理是什么？为什么能防止过拟合？训练和推理时有何不同？',
    answer: 'Dropout 由 Hinton 等提出，训练时每个神经元以概率 p 随机"失活"（输出置零），p 通常取 0.2~0.5，每次前向传播的失活模式不同，相当于在采样不同的子网络。防止过拟合的核心机理有四种解释：(1) 集成学习视角——训练 2^n 个共享权重的子网络的隐式集成，推理时所有神经元都激活（相当于取子网络集合的几何平均），方差降低；(2) 降低神经元共适应（Co-adaptation）——神经元不能依赖特定其他神经元的存在，被迫学习更鲁棒、更独立的特征表示，类似有性繁殖中基因不依赖特定配偶；(3) 特征噪声正则化——Dropout 等价于在隐藏层注入乘性伯努利噪声，迫使网络在信息不完整时仍能做出正确预测，本质是数据增强在特征空间的推广；(4) 贝叶斯近似——Gal & Ghahramani 证明带 Dropout 的网络等价于深度高斯过程的变分推断近似。训练时：对每个 mini-batch 的每个神经元独立抽样 Bernoulli(p) 掩码，失活的神经元输出为 0，同时需按 1/(1-p) 缩放剩余神经元的输出（Inverted Dropout），保持该层总激活值的期望不变，避免推理时需要做额外缩放。推理时：Dropout 关闭，所有神经元参与计算但无需缩放（因为训练时已通过 Inverted Dropout 做了尺度补偿），直接输出确定性结果。实践中 Dropout 放在激活函数后或全连接层之间，通常不对卷积层使用高 Dropout 率（卷积层参数共享本身已有正则化效果）。',
    tags: ['Dropout', '过拟合', '共适应', '集成学习', '正则化'],
