    id: 'ml-65',
    category: 'machine-learning',
    question: '什么是反向传播（Backpropagation）？请推导其数学过程。',
    answer: '反向传播是训练神经网络的核心算法，本质是利用链式法则高效计算损失函数对每个参数梯度的动态规划算法。推导流程：(1) 前向传播：输入 x 逐层通过线性变换 z^{[l]}=W^{[l]}·a^{[l-1]}+b^{[l]} 和激活函数 a^{[l]}=g^{[l]}(z^{[l]})，最终输出 a^{[L]}=ŷ，计算损失 L(y,ŷ)；(2) 反向传播从输出层开始反向递推：输出层误差 δ^{[L]} = ∂L/∂a^{[L]} ⊙ g^{[L]}\'(z^{[L]}) = (a^{[L]}-y)（当损失为交叉熵且激活为 softmax+sigmoid 时的简化形式）；(3) 隐藏层的误差通过链式法则反向传递：δ^{[l]} = [(W^{[l+1]})ᵀ·δ^{[l+1]}] ⊙ g^{[l]}\'(z^{[l]})，即后一层误差经过权重矩阵转置传播并乘以当前层激活函数导数；(4) 最终计算各参数的梯度：∂L/∂W^{[l]} = δ^{[l]}·(a^{[l-1]})ᵀ，∂L/∂b^{[l]} = δ^{[l]}。关键洞察：链式法则使得每层的局部梯度只需计算一次并存储，避免了重复计算指数级膨大的计算图。计算图（Computation Graph）视角更一般化：网络是一个有向无环图，反向传播从损失节点开始，按拓扑逆序遍历各节点计算局部梯度（local gradient）并与上游梯度相乘（chain rule），PyTorch/TensorFlow 的 autograd 引擎即基于此。时间复杂度 O(E)，E 为边数，与前向传播相同量级。',
    tags: ['反向传播', '链式法则', '梯度计算', '深度学习'],
