    category: 'machine-learning',
    question: 'CNN中的卷积层、池化层、全连接层各自的作用是什么？',
    answer: '卷积层（Convolutional Layer）是 CNN 的核心，通过一组可学习的卷积核（滤波器）在输入上滑动做局部加权求和运算。核心作用：(a) 局部连接（稀疏交互）——每个神经元仅连接输入的局部区域（感受野），参数数量与输入尺寸解耦，大幅降低参数量，提取局部特征如边缘/纹理/角点；(b) 参数共享——同一卷积核遍及整个输入，使得检测平移不变的特征成为可能，同时也进一步减少参数量；(c) 平移等变性——输入平移 → 输出特征图对应平移，等价性对分割/检测任务至关重要。池化层（Pooling Layer）：对特征图下采样降低空间维度的无参操作。两种主要方式——最大池化（Max Pooling）保留局部最大值，对微小平移和形变有鲁棒性，且梯度仅反向传播到最大值位置；平均池化（Average Pooling）取局部平均值，保留更多背景信息但弱化了显著特征。池化作用：(a) 降维减少计算量和内存；(b) 增大后续层的感受野（下采样后同样大小的卷积核覆盖更大原始区域）；(c) 提供局部平移不变性（微小位移导致的输出变化被池化窗口吸收）；(d) 防止过拟合（减少参数和特征图尺寸）。全连接层（Fully Connected Layer）：每个输出神经元与所有输入神经元连接，参数数量 = n_in × n_out + n_out。作用：将卷积/池化提取的分布式特征表示映射到最终输出空间（分类概率/回归值），可以看作全局特征混合器。在 CNN 最后通常接 1-2 层全连接层，现代架构如 ResNet/ConvNeXt 倾向于用全局平均池化（GAP）+ 单全连接替代多层全连接，进一步降低参数量。',
    tags: ['CNN', '卷积层', '池化层', '全连接层', '感受野'],
    subTopic: '深度学习基础',
