    id: 'ml-75',
    category: 'machine-learning',
    question: '什么是Ablation Study（消融实验）？在设计实验和研究论文中如何使用？',
    answer: 'Ablation Study（消融实验）指系统地移除/替换模型或方法的某个组件，观察性能变化以量化该组件的贡献，类似"如果拿掉X，模型会变差多少？"。命名源于神经科学中的 ablation（切除脑区观测行为变化），在 ML 论文中是证明方法有效性的核心验证范式。使用方法：(1) 组件消融——逐步移除单个组件并测量性能下降（如从完整模型中去掉 BN 层/Dropout/残差连接/注意力机制中的位置编码等），下降越多说明该组件越关键；(2) 特征/输入消融——逐个移除输入特征或模态（如去掉文本只用图像 vs 多模态融合），衡量各模态/特征对最终性能的贡献比例；(3) 数据量消融——以不同比例（10%/25%/50%/100%）训练模型，画数据量-性能曲线，分析当前瓶颈是算法能力还是数据不足；(4) 架构搜索——用单头替代多头注意力、用 SGD 替代 Adam、调整层数/隐藏维度，研究各架构选择的影响；(5) 训练策略消融——如比较有无 warmup/学习率衰减/预训练的影响。消融实验的设计要点：(a) 保持其他条件不变（控制变量法），每次只改变一个因素，否则无法归因；(b) 使用相同的随机种子和评估协议确保可比；(c) 合理选择 Baseline——最好展现组件从 Baseline 逐步增强到最终模型的递增收益；(d) 统计显著性——小数据集上多次运行报告均值和标准差；(e) 消融表格是论文中最有力的说服工具——第一行是完整模型，后续每行展示移除某一组件后的性能下降，清晰直观。工程实践中消融实验用于模型优化决策——移除冗余组件降低推理延迟/内存。',
