    id: 'ml-76',
    category: 'machine-learning',
    question: '在线学习（Online Learning）和批量学习（Batch Learning）的区别？各自适用什么场景？',
    answer: '批量学习（Batch Learning / Offline Learning）用固定训练集一次性训练模型，模型上线后不再更新，直到下一次重新全量训练部署。优点：训练稳定（全量数据的梯度准确）、模型生命周期可控、离线评估完整、版本管理容易；缺点：无法适应数据分布变化（概念漂移后效果衰减）、训练数据量大时耗时长、存储全部历史数据成本高。适用场景：ImageNet 图像分类、Kaggle 竞赛、数据分布长期稳定且无实时更新需求的场景。在线学习（Online Learning）一次处理一条或一小批样本（stream 数据），模型参数即时更新并丢弃样本，一次只"看"一遍数据。优点：(1) 实时适应数据分布变化（广告推荐/股票交易中用户兴趣/市场模式随时变）；(2) 内存友好——不需要存储历史数据（海量日志流无法全存）；(3) 低延迟——新数据到达即可影响模型；(4) 理论上可处理无限数据流。缺点：梯度噪声大不稳定、参数更新可能"遗忘"旧知识（Catastrophic Interference）、学习率需特别设计。代表算法：SGD 天然可在线学习；FTRL（Follow The Regularized Leader）是 Google 广告点击率预估中业界经典的在线学习算法，每个特征维度的学习率自适应调整；在线 Boosting、Hoeffding Tree 等。实践中常用混合方案：Mini-batch 在线学习——累积小批量样本后用 Mini-batch SGD 更新（平衡稳定性和实时性）；在线学习 + 离线全量校正——每日/每周用积累的最近数据做一次离线全量训练，平滑在线学习的噪声。',
    tags: ['在线学习', '批量学习', 'FTRL', '概念漂移', '流式数据'],
