    id: 'ml-77',
    category: 'machine-learning',
    question: '如何处理模型训练中的过拟合？至少列出8种方法并解释各自的原理。',
    answer: '过拟合的解决策略按机制分类：基于数据的方法：(1) 增加训练数据——最根本的方法，更多样本让模型更难"记住"噪声，数据增强（图像旋转/裁剪/颜色抖动、文本回译/同义词替换）在不收集新数据的条件下增加多样性；(2) 数据增强（Data Augmentation）——通过变换原始数据生成新训练样本，强制模型学到变换不变性，相当于在数据空间做了正则化。基于模型约束的方法：(3) L1/L2 正则化——在损失函数中添加 λ·Σ|w|（L1）或 λ·Σw²（L2），L1 产生稀疏解驱动部分权重为零（天然特征选择），L2 收缩所有权重使其接近零但不为零，等效于在贝叶斯框架下给权重施加先验分布约束；(4) Dropout——训练时随机失活神经元，等效于隐式集成大量子网络，降低神经元间共适应，推理时全部激活作为模型平均；(5) Batch Normalization——每层的标准化操作带有 mini-batch 随机噪声，有轻微正则化效果；(6) 早停（Early Stopping）——监控验证集损失，当不再下降时停止训练，防止模型在训练集上继续"死记硬背"。基于模型结构的方法：(7) 降低模型复杂度——减少层数/隐藏单元/树的深度/叶子数，限制模型容量，本质是控制方差；(8) 剪枝（Pruning，针对决策树）——预剪枝（训练时限制生长）和后剪枝（训练后删除冗余子树），防止树在噪声样本上过度分裂。其他方法：(9) 集成方法——Bagging/Random Forest 通过多模型平均降低方差；(10) 权重衰减（Weight Decay）——与 L2 正则化在 SGD 中数学等价，但 AdamW 中解耦权重衰减与自适应学习率更有效。实践中通常组合 2-3 种方法（如数据增强 + Dropout + 早停），效果远超单一方法。',
    tags: ['过拟合', '正则化', '数据增强', 'Dropout', '早停', '集成学习'],
    subTopic: '模型评估与调优',
