    id: 'ml-78',
    category: 'machine-learning',
    question: '什么是Early Stopping？它的工作原理是什么？为什么可以防止过拟合？',
    answer: 'Early Stopping（早停）是一种通过监控验证集性能来动态决定训练终止时机的正则化技术。工作原理：将数据划分为训练集和验证集，每训练若干步（或每个 epoch）在验证集上评估一次损失或指标，记录历史最优验证损失对应的模型参数（checkpoint）；当验证损失在连续 p 个 epoch（称为 patience/容忍轮数）内不再创新低时，停止训练并恢复到历史最优参数。本质上，Early Stopping 利用了"训练误差单调下降、验证误差先降后升"的现象——训练初期模型学习数据中的通用模式（训练和验证误差同时下降），但随着训练继续，模型开始"记忆"训练集中的噪声和特殊模式（训练误差续降、验证误差始升），早停即在验证误差上升前截断训练。为何能防止过拟合：(a) 限制有效训练轮数，相当于在参数空间中以初始权重为中心构造了一个限制区域（L2 正则化在参数空间中的等价效果——早停以时间维度限制了参数搜索半径）；(b) 相比固定训练 epoch 数，早停自适应数据集和模型复杂度的差异——简单数据自动早停节省算力，复杂数据自动多训练。实践要点：(a) patience 设置 10-20 epoch（太小可能错过暂时的验证损失震荡，太大延迟早停收益）；(b) 配合学习率衰减使用效果更佳；(c) 最终模型不应使用早停的 checkpoint（那是验证集上的最优，有信息泄露），应在早停确定最佳训练轮数后，在全量训练数据上重新训练相同轮数。',
    tags: ['Early Stopping', '早停', '验证集', '过拟合', '正则化'],
    subTopic: '模型评估与调优',
    difficulty: 'easy',
