    id: 'ml-111',
    category: 'machine-learning',
    question: '如何评估文本生成质量？BLEU、ROUGE、Perplexity各自衡量什么？有什么缺陷？',
    answer: '文本生成评估分为自动指标和人工评测，自动指标各有侧重和严重缺陷：(1) BLEU（Bilingual Evaluation Understudy）——基于n-gram精确匹配的指标，衡量候选译文与一个或多个参考译文的n-gram重合度（精确率）。公式：BLEU = BP·exp(Σ_{n=1}^N w_n·log p_n)，p_n为n-gram精确率，w_n通常等权（N=4），BP（Brevity Penalty）是长度惩罚因子（防止过短的翻译骗高分）。BLEU本质是在评估"候选文本的每个n-gram是否在参考中也出现"——即精确度优先，对召回不敏感。缺陷：(a) 忽略同义表达——"迅速"和"快速"完全不同分；(b) 不考虑语法连贯性和语义保真——胡扯但包含许多参考中n-gram的文本可得高分；(c) 只依赖表面n-gram匹配，无法评估事实一致性（摘要是否虚构内容）。BLEU主要用于机器翻译评估。(2) ROUGE（Recall-Oriented Understudy for Gisting Evaluation）——基于召回率的指标，衡量参考文本的n-gram/最长公共子序列（LCS）在候选中有多大比例被覆盖。ROUGE-N = Σ_{S∈Ref} Σ_{gram_n∈S} Count_match(gram_n) / Σ_{S∈Ref} Σ_{gram_n∈S} Count(gram_n)（n-gram召回率）。ROUGE-L使用最长公共子序列（LCS）做比较（不要求连续匹配）。ROUGE侧重覆盖面（Recall），适合摘要评估（候选能否抓取原文关键信息）。缺陷：同样无视语义和事实，且对语句长度异常敏感（暴力堆砌内容可刷高ROUGE）。(3) Perplexity（困惑度）——衡量语言模型对序列"诧异"程度的指标：PPL = exp(-(1/N)·Σ_i log P(w_i | w_{i-1},...,w_1))。等价于模型对序列给的平均概率的倒数，PPL越低→模型对序列的预测越确定（越不"困惑"）。用于评估语言模型本身的内在质量，而非生成文本与参考的相似度。缺陷：只能用训练/测试数据的语言分布做评估，依赖分词方式（不同tokenizer的PPL不能直接比），对被评估数据集质量和重复性敏感。三种指标的集合局限：都无法评估语义忠诚度、事实一致性、创造性（自动指标只会将创造性发散视为"偏离参考"）。因此实践中自动指标仅用于粗劣的模型筛选，最终决策需依赖人工评测（流畅度、忠实度、趣味性等维度打分）或专门的自然语言推断（NLI）模型评估事实一致性。',
    tags: ['BLEU', 'ROUGE', 'Perplexity', '文本生成评估', 'NLP指标'],
    subTopic: 'NLP基础',
