    category: 'machine-learning',
    question: '自监督学习在NLP（BERT、GPT）和CV（SimCLR、MAE）中的预训练范式有何异同？',
    answer: '自监督学习在NLP和CV中的范式差异源于两种数据形态的本质不同。相同点：(1) 核心动机一致——利用大规模无标注数据学出可迁移的通用表示，微调后大幅提升下游任务性能（尤其是数据稀缺的任务）；(2) 训练形式——都采用自监督前置任务（Pretext Task）构造伪标签，通过神经网络+梯度下降学习；(3) 学到的表示——浅层学到通用模式（NLP的词法→语法→语义层次；CV的边缘→纹理→物体部件→物体）、深层学到任务相关的抽象表示；(4) 都证明了大规模数据+大规模模型是提升性能的简单有效途径（Scaling Law）。核心不同点：(1) NLP的预训练以**生成式/自回归**为主——BERT（MLM遮盖语言建模，Encoder-only）学习双向上下文表示，GPT（Next Token Prediction，Decoder-only）学习单向生成能力。预测目标是离散token（从文本片段预测缺失的离散词），损失函数为交叉熵。(2) CV的预训练以**对比学习**为主（SimCLR/MoCo/BYOL）——通过构造正负样本对（两张同一图像的不同增强->正样本，不同图像->负样本）学习表示空间的聚类结构，优化目标是拉近正样本/推远负样本（InfoNCE损失）。晚期CV也出现生成式预训练（MAE遮盖像素重建），思想更贴近MLM。(3) 数据特性决定方法差异——文本是离散符号序列，每个token承载高级语义，因此"预测缺失词"是足够困难且有意义的前置任务。图像是连续像素阵列，像素间信息高度冗余，"预测像素"太简单（易退化为浅层插值），早期生成式预训练在CV长期无法超越监督学习，直到MAE用高遮盖率（75%）将重建变难问题才被解决。而对比学习通过数据增强构建"同语义不改变"的先验，对视觉这种高冗余、高频空间外观变化的数据更自然。(4) 训练稳定性——NLP的生成式自监督训练通常非常稳定（离散token的交叉熵），CV的对比学习对数据增强策略/batch大小/负样本质量敏感，调参困难。(5) 当前融合趋势——Vision Transformer（ViT）架起了两者共享同一Transformer架构的桥梁，多模态模型（CLIP/ALIGN/BLIP）同时用对比学习对齐图文表示、在两者间共享自监督信号，进一步模糊了NLP和CV预训练的边界。',
    tags: ['自监督学习', 'NLP', 'CV', '预训练范式', '对比学习', '生成式'],
