    category: 'machine-learning',
    question: '可解释AI（Explainable AI）与模型公平性有什么关系？透明度如何帮助发现不公平？',
    answer: '可解释AI（XAI）与模型公平性紧密相关，可解释性是检测和验证公平性的前提工具——只有当模型的决策过程和影响因素被解析出来，才能判断这些影响因素是否与敏感属性不正当相关（即是否产生了歧见）。透明化如何帮助发现和纠正不公平：(1) 全局可解释性暴露特征依赖——方法如特征重要性（Permutation Importance、SHAP全局摘要图）揭示模型总体上对哪些特征最依赖。如果发现敏感特征（如种族、性别）或其高度相关的代理特征（如邮编）位居高重要性，则直接显示偏差事实和位置。例如SHAP摘要图可能揭示"性别"成为贷款审批重要决策信号，即使性别本应无关乎还款能力，系统性的不公平就此暴露。(2) 局部可解释性揭示个体不公——对于模型对某个用户做出的不利预测（如被拒贷款），使用LIME（局部近似线性模型）或SHAP值跟踪该特定预测中各特征的贡献。如果该样本的负面预测主要由其敏感特征值驱动而非真实信用指标，个案层面的歧视可被侦破。例如SHAP waterfall图展示"种群=某族"贡献-0.20，"收入=高"贡献+0.12——种群成为最大负面决策因子并压过了正面因子，这就是微观层面歧视的证据。(3) 模型行为的公平性审计——使用可解释方法分析在不同敏感群体上的模型决策逻辑是否一致：(a) 对两个仅敏感属性不同的其他完全相同的虚构样本（Counterfactual Fairness测试），检查SHAP/LIME解释特征归属是否因敏感属性发生翻转。(b) 绘制分群体的Partial Dependence Plot（累积局部效应图），看同一特征对不同群体的预测影响曲线弧度是否一致——如果"年龄"对某族申请人的模型得分负斜率远大于另一族（即在某族中年龄大更不利），则暗示交互偏差。(4) 错误分析的公平维度——当限制群组的性能差距被发现（如FNR差异），可解释性帮助追溯为什--哪些特征对于两个群体预测准确的贡献模式不同。若发现某群体常因为其特征"居住时间短"而被拒，就能追溯到历史采样偏差或社会壁垒在该特征上放了不公平权重。(5) 规则提取与伪特征对抗——通过决策树的规则提取或局部可视化，可清晰看到模型中是否产生了类似"族裔==X→负面决定"的显式划分。一旦发现了歧视性决策规则，可进一步用对抗方法或其他in-process方法对付该特征通路。XAI工具在公平性上的典型框架：(a) SHAP依赖图和交互值的公平审计，(b) Fairlearn的公平性指标检查+模型可解释，(c) What-If Tool（交互式探索不同公平性定义下分类阈值的对比，同时查看每个个体特征贡献）。然而XAI也有限制：(a) 解释方法的精度有限（LIME的线性近似可能错过复杂交互）、(b) 当模型公平性来源于复杂非线性交互（而非简单单特征效应）时，目前SHAP交互值只能处理二阶交互但无法充分可视化高阶关联不公、(c) 可解释性只能"暴露"偏差，实施去偏还需要额外的干预机制。综上，可解释AI是公平性诊断的首选"显微镜"，没有它的大部分场景下，模型的不公将永处于"黑盒"状态，无法被系统审查和改良。',
