    id: 'ml-141',
    category: 'machine-learning',
    question: '什么是LDA（Linear Discriminant Analysis）？监督降维与PCA这种无监督降维的本质区别？',
    answer: 'LDA（Linear Discriminant Analysis，线性判别分析）是一种监督线性降维方法，目标是寻找低维投影方向，使得投影后同类样本尽量聚集（类内散度最小）、不同类样本尽量分离（类间散度最大）。数据有K个类别，类内散度矩阵 S_W = Σₖ Σ_{x∈Cₖ} (x-μₖ)(x-μₖ)ᵀ，类间散度矩阵 S_B = Σₖ nₖ (μₖ-μ)(μₖ-μ)ᵀ，其中μₖ为类k均值，μ为全局均值，nₖ为类k样本数。LDA的优化目标为最大化广义Rayleigh商 J(w) = (wᵀS_B w) / (wᵀS_W w)，等价于求解广义特征值问题 S_B w = λ S_W w。取前K-1个最大特征值对应的特征向量作为投影方向（因S_B的秩最多为K-1，故LDA最多将数据降至K-1维）。监督降维（如LDA）与无监督降维（如PCA）的本质区别：(1) 优化目标不同——PCA最小化重建误差，找到数据变化最大的方向（方差最大），完全不考虑类别信息；LDA最大化类别可区分性，找到类间分离最大化/类内压缩化的方向。直观上，对于由两个重叠类别组成的纺锤形分布数据（沿X轴方差最大但类重叠严重，沿Y轴上两个类干净分离），PCA的第一主成分沿X轴（高方差但类混叠），LDA的投影方向沿Y轴（分类最优）。(2) 对数据结构假设不同——PCA假设"方差大"的方向是"信息量大"的方向（即信号=方差），在视觉/图像数据的降维中方差确实对应信号，但在分类任务中方差大的方向可能是无类别区分度的噪声轴（如光照变化）；LDA假设"类间散度/类内散度比的极大方向"是对分类最优的方向，直接使用标签信号指导降维。(3) 失败模式——PCA在数据方差噪声主导时可能丢掉关键小方差分类信号（如少数类别占比1%但在小方差方向上分布特殊，主成分会将它们与噪声一并抹除）。LDA的失败模式是当S_W奇异时（特征数远大于样本数，小样本问题）无法直接求解，需要预先降维（PCA->LDA流水线，或使用正则化LDA/SW+λI）或者是S_B退化时（类中心在一条线上，K-1个有效方向中大部分无意义）。(4) 对离群点的敏感度——PCA对离群方差膨胀敏感（异常点的高方差辐射把主成分方向扯离主要数据方向），LDA对离群均值同样敏感。(5) 最大降维维度——PCA最多可降到min(n,d)维，其中每一维都方差最大化且正交；LDA最多可降到K-1维（类别间散度矩阵秩=K-1），对于二分类问题只能降为1维（投影成一条线上的点，该线称为Fisher判别线）。(6) 实际选择——PCA是无监督通用压缩/可视化首选（无需标签），LDA在标注数据可用时作为分类任务的特征预提取工具（可用于降维后的分类或预处理嵌入）。工程中的常见做法是PCA(降噪维) + LDA(分类维)组合使用：(a) PCA降到n-K_c维（保证S_W非奇异），(b) 再LDA降到K-1维。综合评价：PCA是"保留信息"，LDA是"保留判别力"，前者用于重建和表示学习，后者用于分类嵌入，二者解决的问题高度不同，但同时与"信息瓶颈论"交织。',
    tags: ['LDA', 'PCA', '监督降维', '无监督降维', 'Fisher判别', '散度矩阵'],
