    id: 'ml-146',
    category: 'machine-learning',
    question: '异常检测的三大方法类型：监督、半监督、无监督方法各自适用什么场景？',
    answer: '异常检测（Anomaly Detection）根据标签可用性分为监督、半监督、无监督三大类，适用不同的实际场景。监督异常检测——训练集包含完整标签（正常/异常标注），直接建模为分类问题。但实际中异常检测面临极致的类别不平衡（异常 远少 正常），常规分类器将无法有效。需用处理不平衡的特殊手段：(a) 重采样（SMOTE/ADASYN对异常过采样+Normal降采样）、(b) 类别加权损失、(c) 专门的代价敏感学习（异常漏报成本 >> 误报）。适用场景：有充足标注异常的领域——信用卡欺诈检测（银行有历史欺诈案件记录可标注）、网络入侵检测（安全专家对已知攻击模式分类）、缺陷检测（产线工人标记缺陷样张）。监督方法的优势是能利用已知异常模式获得强区分力，劣势是缺乏面对未知异常的泛化能力（只能检测训练集中有的异常类型）。半监督异常检测（又称One-Class Classification, 一类分类器）——仅拥有正常类样本的标注（或假设训练集全为正常，或仅标记正常资料）。模型学出一个包围正常数据范围的决策边界，用以界定何为"正常样"，测试时不属于正常分布的数据被识别为异常。代表方法：(a) One-Class SVM——寻找包含最多正常数据的最小球形边界，边界外点为异常；(b) SVDD（Support Vector Data Description）——类似思想，(c) 深度半监督——AutoEncoder在正常数据上训练重构，测试时如果重构误差异常高→判断为异常（其隐特征无法有效表达该输入）；同样GANomaly通过GAN只学正常分布，重建+判别双通道异常判定。适用场景：(a) 仅有正常数据可标注，异常数据未知不可标注——比如设备故障数据（正常工作时大量读数易获得，机器损坏前数据极少并无法预测）、(b) 检测新出现的异常——不需提前见过异常类型。无监督异常检测——无任何标签，仅从数据本身的统计/结构规律推断异常。假设：正常数据聚集在低维区域、频率高、密度大；异常数据稀疏或离群。代表方法：(a) 基于距离——如KNN离群分数（到K近邻的平均距离），(b) 基于密度—— LOF（Local Outlier Factor）、(c) 基于聚类—— DBSCAN天然识别噪声点为异常、(d) 基于树——孤立森林（Isolation Forest）、(e) 降维方法——PCA重构误差大、自编码器重构误差，(f) 基于统计分布——假设数据服从多元高斯，马氏距离大的标记为异常（Elliptic Envelope）。适用场景：(a) 对数据一无所知，无任何标签可用（如初期新系统上线后的异常监控），(b) 探索性数据分析中寻找离群点，(c) 高维/大数据量场景中需要快速筛选出可疑样本以进行下一步人工排查（孤立森林很合适）。选择指南：监督——代表真实的异常检测场景最理想但成本最高（标注+处理不平衡）、半监督——正常数据丰富但异常穷乏的实际首选（如运维异常检测）、无监督——抓取潜在问题供进一步审查的快速扫描（如日志清洗、数据质量筛选）。实践中，常将半/无监督作为缺省基线，结合业务反馈逐步升级为带监督的异常检测 pipeline。同时必须处理正常分布的变化/漂移（运维中机器升级→正常信号特征改变→旧One-Class SVM失效→需定期重训）。',
    tags: ['异常检测', '监督', '半监督', '无监督', 'One-Class', '孤立森林'],
    subTopic: '异常检测',
