    category: 'machine-learning',
    question: '【场景题】你的训练数据有1亿条，特征维度5000，你只有一台16GB内存的机器，如何训练一个分类模型？',
    answer: '1亿样本×5000维特征在16GB内存下无法直接载入做全量训练（假设float32存储，仅特征矩阵就需1e8×5e3×4≈1.9TB，即使稀疏假设——如稀疏率99%约20GB仍超限）。需综合利用以下几种策略组合来实现训练。1. 特征维度降维/筛选（减少特征数→缩小单batch内存）：(a) 先取可载入内存的一个采样（合理采样~100K-1M用分层采样保持分布）当成Filter评估，通过方差阈值消除常量特征/低方差，以及互信息/Chi-Square选择与目标高关联的特征，把5000维→2000维；(b) 对高度共线的特征进行聚类分组，用组内具有代表性的特征(single linkage cut 子)替整组。之后再Embedded特征选择——在小采样上用带L1的逻辑回归/LightGBM训练找出前N重要特征（重要性贡献90%累积），锁定重要特征子集（~500维）。这一过程完全在内存安全范围内完成。2. 迭代式/在线学习——不一次性加载所有数据，外部存储器以流式逐个/批读入训练。SGDClassifier(sklearn)/SGDRegressor 的 partial_fit 接口：每次将数据按mini-batch迭代载入→更新权重→释放该批数据→读下一批，所有数据不驻留。SAG (Stochastic Average Gradient)用增量均值估算梯度。需选用带L1/L2的logistic reg或SVM线性核。设置学习率衰减公式。通过全数据扫描→内存峰值仅每批(B)大小（如1万条×小特征维度占用~200MB）。关键注意点：(a) 需要在epoch之间shuffle数据到磁盘（如按块shuffle）防止排序偏置，(b) 参数正则化和早停需要用独立的验证集（在线评估）。3. 分块+集成训练——数据分成若干chunk（每个chunk内存装得下），每个chunk单独训练一个子模型（如每个5M样本×500维~约10G内存），产出一组子模型（树模型或线性模型），在推理新样本时集成——可平均概率(Mean-of-Probabilities)。这种方式类似Bagging且样本天然分块无放回（Pasting)。优势全内存单chunk训练不限制模型类型。推理时需要保存多模型但可叠加。4. 用树模型的批处理采样——LightGBM支持使用内存外在磁盘/内存映射读取数据（通过设置two_round_loading=true会先搜集统计再释放然后再加载）。可启动pre_partition参数二分数据读取+梯度计算。对GBDT可大量采样+分bin降低内存（max_bin调低如64，限制每数据处内存，相比>255可压至约1/4）。5. 利用量化和数据结构技巧——尽量使用稀疏格式（CSR/CSC）存储特征，因5000维可能存在大量零（如one-hot→稀疏），内存降级。数据精度使用float16/32。若用XGBoost，可通过外存模式训练(直接读libsvm/csr文件)。6. 混合方式选最佳路径：(a) 先用方法1降维到500维，(b) 用方法2 SGDClassifier partial_fit扫全量做一次线性LR baseline并给出初筛。(c) 对选出的高重要性样本/特征子集再开启方法3或方法4，在可控时间段内训练出最终模型。选择策略需考虑目标：如果需要快速可分析模型→LR SGD+特征子集；如果高精度不可妥协→分块GBDT Bagging（虽然成本更高）。此时模型存储大，但推理时通过投票/平均获取预测。最后必须考虑交叉验证策略——在这种受限条件下CV无法做K-fold。替代方案：用预留的时间切片验证集+提前单次验证评估模型收敛和性能（Hold-Out）。记录下验证集AUC和loss曲线做模型选择。上线后持续在线监控预测分布和精度做兜底。即使用小内存机器，采用正确的逐批训练/降维/分块集成，依然能够在可接受时间内训练出一个足够性能的分类模型。',
    tags: ['场景题', '大数据', '内存受限', 'SGD', '分块训练', 'GBDT'],
